function h(string $s): string { return htmlspecialchars($s, ENT_QUOTES, 'UTF-8'); }
function fail(string $m, int $code=400): never { http_response_code($code); echo '<!doctype html><meta charset="utf-8"><style>body{font:15px Arial;background:#f4f7fa;padding:35px;color:#17212b}.b{max-width:780px;margin:auto;background:#fff;border:1px solid #d9e0e6;border-radius:14px;padding:24px}a{color:#174f86}</style><div class="b"><h1>RFQ email could not be sent</h1><p>'.h($m).'</p><p><a href="rfq-list.php">Return to RFQs</a></p></div>'; exit; }
function cleanHeader(string $v): string { return trim(str_replace(["\r","\n"],'',$v)); }
function parseEmailList(string $v): array { $out=[]; foreach(preg_split('/[;,]+/',$v) as $e){$e=trim($e);if($e===''||!filter_var($e,FILTER_VALIDATE_EMAIL))continue;$out[strtolower($e)]=$e;} return array_values($out); }
function pdfText(string $s): string { $s=iconv('UTF-8','Windows-1252//TRANSLIT//IGNORE',$s)?:$s; return str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$s); }
function pdfUri(string $s): string { return str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$s); }
function buildPdf(array $d, string $pricingUrl=''): string {
    // Polished RFQ PDF layout v2026-09-18: branded header, structured requirement table, clickable pricing CTA.
    // Prefer a dedicated JPEG for PDF embedding so the logo works even when GD is not enabled.
    // Put lowe-logo-pdf.jpg in /images alongside the normal website logo.
    $logoJpeg=null;$logoW=0;$logoH=0;
    $jpegCandidates=[
        __DIR__.'/images/lowe-logo-pdf.jpg',
        __DIR__.'/images/lowe-logo.jpg',
        __DIR__.'/images/lowe-logo.jpeg'
    ];
    foreach($jpegCandidates as $logoPath){
        if(!is_file($logoPath)||!is_readable($logoPath)) continue;
        $info=@getimagesize($logoPath);
        if($info && ($info['mime']??'')==='image/jpeg'){
            $bytes=@file_get_contents($logoPath);
            if($bytes!==false && $bytes!==''){
                $logoJpeg=$bytes;$logoW=(int)$info[0];$logoH=(int)$info[1];
                break;
            }
        }
    }
    // Self-contained fallback: the official Lowe logo is embedded in this PHP file.
    // This ensures the PDF always has the logo even if a separate image file is missing.
    if($logoJpeg===null){
        $embeddedLogo=base64_decode('', true);
        if($embeddedLogo!==false){
            $logoJpeg=$embeddedLogo;
            $embeddedInfo=@getimagesizefromstring($logoJpeg);
            if($embeddedInfo){$logoW=(int)$embeddedInfo[0];$logoH=(int)$embeddedInfo[1];}
        }
    }

    // Last fallback: convert the website PNG to JPEG when GD is available.
    if($logoJpeg===null){
        $pngPath=__DIR__.'/images/lowe-logo.png';
        if(is_file($pngPath)&&is_readable($pngPath)&&function_exists('imagecreatefromstring')&&function_exists('imagejpeg')){
            $raw=@file_get_contents($pngPath);
            $srcImg=$raw!==false?@imagecreatefromstring($raw):false;
            if($srcImg){
                $w=imagesx($srcImg);$h=imagesy($srcImg);
                $canvas=imagecreatetruecolor($w,$h);
                $white=imagecolorallocate($canvas,255,255,255);
                imagefill($canvas,0,0,$white);
                imagealphablending($canvas,true);
                imagecopy($canvas,$srcImg,0,0,0,0,$w,$h);
                ob_start();imagejpeg($canvas,null,94);$logoJpeg=ob_get_clean();
                $logoW=$w;$logoH=$h;
                imagedestroy($canvas);imagedestroy($srcImg);
            }
        }
    }

    $content='';
    $text=function(float $x,float $y,float $size,string $value,string $font='F1',string $color='0.10 0.14 0.18')use(&$content){
        $content.="BT /{$font} {$size} Tf {$color} rg {$x} {$y} Td (".pdfText($value).") Tj ET\n";
    };
    $fill=function(float $x,float $y,float $w,float $h,string $color)use(&$content){
        $content.="q {$color} rg {$x} {$y} {$w} {$h} re f Q\n";
    };
    $stroke=function(float $x,float $y,float $w,float $h,string $color='0.82 0.86 0.89',float $lw=0.7)use(&$content){
        $content.="q {$color} RG {$lw} w {$x} {$y} {$w} {$h} re S Q\n";
    };
    $line=function(float $x1,float $y1,float $x2,float $y2,string $color='0.86 0.89 0.92',float $lw=0.6)use(&$content){
        $content.="q {$color} RG {$lw} w {$x1} {$y1} m {$x2} {$y2} l S Q\n";
    };
    $wrap=function(string $value,int $chars=48):array{
        $value=trim($value);
        if($value==='')$value='Not specified';
        return explode("\n",wordwrap($value,$chars,"\n",true));
    };
    $value=function($v):string{ $v=trim((string)$v); return $v!==''?$v:'Not specified'; };

    // Page background and branded header.
    $fill(0,0,612,792,'1 1 1');
    $fill(0,710,612,82,'0.047 0.137 0.251');
    $fill(0,706,612,4,'0.843 0.098 0.118');

    // Header: keep the logo, title and RFQ block in distinct zones so nothing overlaps.
    if($logoJpeg!==null){
