        $fill($logoBoxX,$logoBoxY,$logoBoxW,$logoBoxH,'1 1 1');
        $pad=7;
        $maxW=$logoBoxW-($pad*2);$maxH=$logoBoxH-($pad*2);
        $ratio=$logoW/max(1,$logoH);
        $drawW=$maxW;$drawH=$drawW/$ratio;
        if($drawH>$maxH){$drawH=$maxH;$drawW=$drawH*$ratio;}
        $drawX=$logoBoxX+($logoBoxW-$drawW)/2;
        $drawY=$logoBoxY+($logoBoxH-$drawH)/2;
        $content.=sprintf("q %.2f 0 0 %.2f %.2f %.2f cm /Im1 Do Q\n",$drawW,$drawH,$drawX,$drawY);
    }else{
        // Compact fallback only; it will not intrude into the title area.
