        $text(50,$rowY+2,7.5,$left[$i][0],'F2','0.35 0.41 0.47');
        $lv=$wrap($left[$i][1],24);$text(125,$rowY+2,8.5,$lv[0],'F1','0.10 0.14 0.18');
        $text(328,$rowY+2,7.5,$right[$i][0],'F2','0.35 0.41 0.47');
        $rv=$wrap($right[$i][1],23);$text(408,$rowY+2,8.5,$rv[0],'F1','0.10 0.14 0.18');
        $line(38,$rowY-7,574,$rowY-7,'0.88 0.90 0.92',0.45);
        $rowY-=25;
    }
    $stroke(38,469,536,132,'0.82 0.86 0.89',0.7);

    // Notes callout.
    $text(38,446,10,'SPECIAL REQUIREMENTS / NOTES','F2','0.047 0.137 0.251');
    $fill(38,400,536,38,'0.985 0.972 0.925');
    $stroke(38,400,536,38,'0.88 0.77 0.39',0.7);
    $noteLines=$wrap($value($d['notes']),95);
    $text(50,422,8.5,$noteLines[0],'F1','0.20 0.20 0.17');
    if(isset($noteLines[1]))$text(50,409,8.5,$noteLines[1],'F1','0.20 0.20 0.17');

    // Supplier response checklist in two columns.
    $text(38,374,12,'SUPPLIER RESPONSE REQUESTED','F2','0.047 0.137 0.251');
    $fill(38,249,536,112,'0.970 0.979 0.986');
    $stroke(38,249,536,112,'0.80 0.85 0.89',0.7);
    $items=['Price and price unit','Freight method (FOB / Delivered / Prepaid & Add)','FOB location','Minimum order','Lead time','Availability','Payment terms','Country of origin','Quote expiration','Freight / surcharges','Manufacturer'];
    $leftItems=array_slice($items,0,6);$rightItems=array_slice($items,6);
    $iy=340;
    foreach($leftItems as$item){$text(52,$iy,8.7,'- '.$item,'F1','0.12 0.16 0.20');$iy-=16;}
    $iy=340;
    foreach($rightItems as$item){$text(322,$iy,8.7,'- '.$item,'F1','0.12 0.16 0.20');$iy-=16;}

    // Return instruction.
    $fill(38,202,536,34,'0.945 0.966 0.953');
    $stroke(38,202,536,34,'0.62 0.79 0.68',0.7);
    $text(50,221,8.5,'Please submit pricing through the secure Lowe Chemical form below.','F2','0.09 0.35 0.22');
    $text(50,208,7.8,'Questions: '.SOURCING_EMAIL.'  |  Reference '.$value($d['rfq']),'F1','0.22 0.34 0.28');

    // Clickable call-to-action.
    $annots='';$linkObjNo=8;
    if($pricingUrl!==''){
        $buttonX=164;$buttonY=126;$buttonW=284;$buttonH=42;
        $fill($buttonX,$buttonY,$buttonW,$buttonH,'0.090 0.380 0.235');
        $text(231,$buttonY+16,12,'SUBMIT PRICING ONLINE','F2','1 1 1');
        $text(178,108,7.5,'Click the button to open the secure pricing form for this RFQ.','F1','0.15 0.30 0.46');
