function buildEmailHtml(array $d, string $pricingUrl=''): string {
    $row=fn($a,$b)=>'<tr><td style="padding:7px 10px;border-bottom:1px solid #e5e9ed;color:#5b6670;width:34%;font-weight:bold">'.h($a).'</td><td style="padding:7px 10px;border-bottom:1px solid #e5e9ed">'.h($b?:'Not specified').'</td></tr>';
    $table='';
    foreach([
        ['RFQ',$d['rfq']],['Pricing Needed By',$d['pricing_needed_by']],['Product Name',$d['product_name']],['CAS Number',$d['cas_number']],
        ['Product Grade',$d['product_grade']],['Packaging',$d['packaging']],['Container Weight',$d['container_weight']],['Quantity',$d['quantity']],
        ['Price Basis Requested',$d['price_basis']],['Delivery',$d['delivery']],['Estimated Annual Usage',$d['annual_usage']],
        ['Requirement Type',$d['requirement_type']],['Special Requirements / Notes',$d['notes']]
    ] as [$a,$b]) $table.=$row($a,$b);

    $pricingBlock='';
    if($pricingUrl!==''){
        $safeUrl=h($pricingUrl);
        $pricingBlock='<div style="margin:26px 0 22px;text-align:center">'
            .'<a href="'.$safeUrl.'" style="display:inline-block;background:#17613c;color:#ffffff;text-decoration:none;font-weight:bold;font-size:16px;padding:14px 26px;border-radius:8px">SUBMIT PRICING</a>'
            .'<div style="margin-top:12px;font-size:12px;color:#66717d">Use the secure Lowe Chemical pricing form for this RFQ.</div>'
            .'</div>'
            .'<div style="background:#f4f7fa;border:1px solid #d9e0e6;border-radius:8px;padding:12px 14px;margin:0 0 20px;font-size:12px;color:#4f5b66">'
            .'<strong>If the button does not open:</strong><br><a href="'.$safeUrl.'" style="color:#174f86;word-break:break-all">'.$safeUrl.'</a>'
            .'</div>';
    }

    return '<!doctype html><html><body style="font-family:Arial,Helvetica,sans-serif;color:#17212b;background:#f5f7f9;margin:0;padding:24px">'
        .'<div style="max-width:760px;margin:auto;background:#fff;border:1px solid #d9e0e6;border-radius:10px;overflow:hidden">'
        .'<div style="background:#0c2340;color:#fff;padding:20px"><img src="https://lowechemical.com/images/lowe-logo.png" alt="Lowe Chemical Company" style="max-height:58px;max-width:250px;background:#fff;padding:4px;border-radius:4px"><div style="font-size:20px;font-weight:bold;margin-top:10px">Request for Pricing</div></div>'
        .'<div style="padding:22px"><p>Hello,</p><p>Lowe Chemical Company is requesting pricing for the requirement below. Please reference <strong>'.h($d['rfq']).'</strong> in your response.</p>'
        .'<table style="width:100%;border-collapse:collapse;border:1px solid #e5e9ed">'.$table.'</table>'
        .$pricingBlock
        .'<h3 style="color:#0c2340;margin-top:22px">Please provide</h3><ul><li>Price and price unit</li><li>Freight method (FOB / Delivered / Prepaid &amp; Add)</li><li>FOB location</li><li>Minimum order</li><li>Lead time</li><li>Availability</li><li>Payment terms</li><li>Country of origin</li><li>Quote expiration</li><li>Freight / surcharges</li><li>Manufacturer</li></ul>'
        .'<p><strong>Submit your quotation using the secure pricing button above.</strong></p><p>If you need assistance, contact <a href="mailto:'.h(SOURCING_EMAIL).'">'.h(SOURCING_EMAIL).'</a>.</p>'
        .'<p>Thank you,<br>'.h($d['requester_name']).'<br>Lowe Chemical Company</p></div></div></body></html>';
}
function buildEmailMessage(array $d, array $rfq, string $pricingUrl=''): array {
    $subject = cleanHeader($rfq['email_subject'] ?: 'Lowe Chemical Request for Pricing') . ' | ' . $d['rfq'] . ' | ' . $d['product_name'];
    $boundary = '=_LoweRFQ_' . bin2hex(random_bytes(12));
    $headers = [
        'From: ' . LOWE_FROM_NAME . ' <' . LOWE_FROM_EMAIL . '>',
        'Reply-To: ' . SOURCING_EMAIL,
        'MIME-Version: 1.0',
        'Content-Type: multipart/mixed; boundary="' . $boundary . '"'
    ];
    $html = buildEmailHtml($d, $pricingUrl);
    $body = '--' . $boundary . "\r\n" .
        "Content-Type: text/html; charset=UTF-8\r\n" .
        "Content-Transfer-Encoding: 8bit\r\n\r\n" .
        $html . "\r\n";

    if (($rfq['email_format'] ?? '') === 'email_pdf') {
        $pdf = buildPdf($d, $pricingUrl);
        $filename = preg_replace('/[^A-Za-z0-9._-]/', '_', $d['rfq'] . '_' . $d['product_name']) . '.pdf';
        $body .= '--' . $boundary . "\r\n" .
            'Content-Type: application/pdf; name="' . $filename . '"' . "\r\n" .
            'Content-Disposition: attachment; filename="' . $filename . '"' . "\r\n" .
            "Content-Transfer-Encoding: base64\r\n\r\n" .
            chunk_split(base64_encode($pdf)) . "\r\n";
    }

    $body .= '--' . $boundary . "--\r\n";
    return [$subject, $headers, $body];
}

function getSupplierPricingToken(PDO $pdo, int $rfqSupplierId): string {
    // Reuse an active, unexpired token when possible so resends keep the same secure link.
    $q=$pdo->prepare('SELECT id,access_token,expires_at FROM rfq_supplier_access WHERE rfq_supplier_id=? AND is_active=1 ORDER BY id DESC LIMIT 1');
    $q->execute([$rfqSupplierId]);
    $existing=$q->fetch();
    if($existing){
        $token=(string)($existing['access_token']??'');
        $expired=!empty($existing['expires_at']) && strtotime((string)$existing['expires_at'])<time();
        if(preg_match('/^[a-f0-9]{64}$/',$token) && !$expired) return $token;
        if($expired){
            $pdo->prepare('UPDATE rfq_supplier_access SET is_active=0 WHERE id=?')->execute([(int)$existing['id']]);
        }
    }

    $token=bin2hex(random_bytes(32));

    // Build the INSERT from the columns that actually exist in the installed table.
    $columns=[];
    foreach($pdo->query('SHOW COLUMNS FROM rfq_supplier_access')->fetchAll(PDO::FETCH_ASSOC) as $col){
        $columns[(string)$col['Field']]=true;
    }
    foreach(['rfq_supplier_id','access_token','is_active'] as $required){
        if(empty($columns[$required])) throw new RuntimeException('rfq_supplier_access is missing required column: '.$required);
    }

    $fields=['rfq_supplier_id','access_token','is_active'];
    $values=[$rfqSupplierId,$token,1];
    $marks=['?','?','?'];
    if(!empty($columns['expires_at'])){
        $fields[]='expires_at';
        $marks[]='DATE_ADD(NOW(), INTERVAL 30 DAY)';
    }
    $sql='INSERT INTO rfq_supplier_access ('.implode(',',$fields).') VALUES ('.implode(',',$marks).')';
    $pdo->prepare($sql)->execute($values);
    return $token;
}

function supplierPricingUrl(string $token): string {
    return 'https://lowechemical.com/supplier-quote.php?token='.rawurlencode($token);
}

function sendSupplierMail(string $supplierEmail, array $d, array $rfq, string $pricingUrl): bool {
    [$subject, $headers, $body] = buildEmailMessage($d, $rfq, $pricingUrl);
    return mail($supplierEmail, $subject, $body, implode("\r\n", $headers));
}
function sendInternalCopy(array $d, array $rfq): void {
    $internal = [];
    if (!empty($rfq['cc_sourcing'])) $internal[] = SOURCING_EMAIL;
    if (!empty($rfq['cc_requester']) && !empty($rfq['requester_email'])) $internal[] = (string)$rfq['requester_email'];
    foreach (parseEmailList((string)($rfq['additional_cc'] ?? '')) as $e) $internal[] = $e;
    $internal = array_values(array_unique(array_filter($internal, fn($e) => filter_var($e, FILTER_VALIDATE_EMAIL))));
    if (!$internal) return;

    [$subject, $headers, $body] = buildEmailMessage($d, $rfq, '');
    foreach ($internal as $email) {
        @mail($email, '[COPY] ' . $subject, $body, implode("\r\n", $headers));
    }
}
