    'quantity'=>(string)$rfq['quantity'].' '.(string)$rfq['quantity_uom'],
    'price_basis'=>(string)$rfq['price_basis'],
    'delivery'=>trim($rfq['ship_city'].', '.$rfq['ship_state'].' '.$rfq['ship_zip']),
    'annual_usage'=>(string)$rfq['estimated_annual_usage'],
    'requirement_type'=>(string)$rfq['requirement_type'],
    'notes'=>(string)$rfq['special_requirements']
];

$oldStatus=$rfq['status'];
$results=[];
$successCount=0;
$failedCount=0;

foreach($suppliers as $sup){
    $email=trim((string)$sup['contact_email']);
    $supplierName=trim((string)$sup['supplier_name']);
    if($email==='' || !filter_var($email,FILTER_VALIDATE_EMAIL)){
        $results[]=['supplier'=>$supplierName ?: 'Supplier','email'=>$email,'sent'=>false,'error'=>'Missing or invalid supplier email address.','pricing_url'=>''];
        $failedCount++;
        try{$pdo->prepare("UPDATE rfq_suppliers SET email_status='Failed' WHERE id=?")->execute([(int)$sup['id']]);}catch(Throwable $ignore){}
        continue;
    }

    $ok=false;$err='';$pricingUrl='';
    try{
        $token=getSupplierPricingToken($pdo,(int)$sup['id']);
        $pricingUrl=supplierPricingUrl($token);
        $ok=sendSupplierMail($email,$d,$rfq,$pricingUrl);
        if(!$ok) $err='SiteGround/PHP mail() did not accept the message for delivery.';
    }catch(Throwable $e){$err=$e->getMessage();}

    if($ok){
        $successCount++;
        try{$pdo->prepare("UPDATE rfq_suppliers SET email_status='Sent', sent_at=NOW() WHERE id=?")->execute([(int)$sup['id']]);}catch(Throwable $ignore){}
    }else{
        $failedCount++;
        try{$pdo->prepare("UPDATE rfq_suppliers SET email_status='Failed' WHERE id=?")->execute([(int)$sup['id']]);}catch(Throwable $ignore){}
    }
    $results[]=['supplier'=>$supplierName ?: 'Supplier','email'=>$email,'sent'=>$ok,'error'=>$err,'pricing_url'=>$pricingUrl];
}

$sent=($successCount>0 && $failedCount===0);
$newStatus=$sent?'Sent':($successCount>0?'Partially Sent':$oldStatus);

try{
    $pdo->beginTransaction();
    if($sent){
        $pdo->prepare("UPDATE rfqs SET status='Sent' WHERE id=?")->execute([$id]);
        $note='RFQ emailed directly to '.$successCount.' supplier recipient'.($successCount===1?'':'s').'.';
    }elseif($successCount>0){
        $pdo->prepare("UPDATE rfqs SET status='Ready for Email' WHERE id=?")->execute([$id]);
        $note='RFQ email partially sent: '.$successCount.' succeeded, '.$failedCount.' failed.';
    }else{
        $note='RFQ email attempt failed for all supplier recipients.';
    }
    $pdo->prepare('INSERT INTO rfq_status_history (rfq_id,old_status,new_status,changed_by,note) VALUES (?,?,?,?,?)')
        ->execute([$id,$oldStatus,$sent?'Sent':$oldStatus,$rfq['requester_email'],$note]);
    $pdo->commit();
}catch(Throwable $e){
    if($pdo->inTransaction())$pdo->rollBack();
    fail('The email attempt completed, but the database status could not be updated: '.$e->getMessage(),500);
}

if($successCount>0){
    sendInternalCopy($d,$rfq);
}

$err=$failedCount>0 ? 'One or more supplier emails were not accepted for delivery. See the details below.' : '';
unset($_SESSION['rfq_send_csrf']);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= h($rfq['rfq_number']) ?> | Lowe Chemical</title><style>body{margin:0;background:#f4f7fa;color:#17212b;font:15px/1.5 Arial,sans-serif}.top{background:#0c2340;color:#fff;padding:20px}.top div,.box{max-width:800px;margin:auto}.top img{max-height:50px;background:#fff;padding:3px;border-radius:4px}.box{background:#fff;border:1px solid #d9e0e6;border-radius:14px;padding:25px;margin-top:28px}h1{color:#0c2340}.ok{background:#e7f4ec;border-left:4px solid #17613c;padding:13px}.bad{background:#fff5f5;border-left:4px solid #a62929;padding:13px}.btn{display:inline-block;margin-top:18px;margin-right:8px;text-decoration:none;border-radius:9px;padding:10px 15px;font-weight:700;background:#0c2340;color:#fff}.secondary{background:#e9eef3;color:#243646}</style></head><body><div class="top"><div><img src="images/lowe-logo.png" alt="Lowe Chemical"></div></div><div class="box"><h1><?= $sent?'RFQ email sent':'RFQ email was not sent' ?></h1><p><strong><?= h($rfq['rfq_number']) ?></strong></p><?php if($sent): ?><div class="ok">The RFQ was submitted directly to <?= (int)$successCount ?> supplier recipient<?= $successCount===1?'':'s' ?>. The database status is now <strong>Sent</strong>.</div><?php else: ?><div class="bad"><?= h($err ?: 'The RFQ email was not sent.') ?></div><?php endif; ?><div style="margin-top:16px"><strong>Delivery attempt details</strong><?php foreach($results as $r): ?><div style="margin-top:8px;padding:9px 11px;border:1px solid #d9e0e6;border-radius:8px"><strong><?= h($r['supplier']) ?></strong> &lt;<?= h($r['email']) ?>&gt; — <?= $r['sent'] ? '<span style="color:#17613c;font-weight:700">ACCEPTED BY MAIL SERVER</span>' : '<span style="color:#a62929;font-weight:700">FAILED</span>' ?><?php if(!$r['sent'] && $r['error']): ?><div style="margin-top:4px;color:#a62929"><?= h($r['error']) ?></div><?php endif; ?><?php if($r['sent'] && !empty($r['pricing_url'])): ?><div style="margin-top:4px;color:#17613c;font-size:12px">Secure Submit Pricing link included.</div><?php endif; ?></div><?php endforeach; ?></div><a class="btn" href="rfq-view.php?id=<?= (int)$id ?>">Return to RFQ</a><a class="btn secondary" href="rfq-list.php">RFQ List</a></div></body></html>
